import{_ as e,o as t,c as r,a2 as o}from"./chunks/framework.CjAa9jTu.js";const u=JSON.parse('{"title":"Prácticas de laboratorio con PY32F003","description":"","frontmatter":{},"headers":[],"relativePath":"examples/index.md","filePath":"examples/index.md"}'),i={name:"examples/index.md"};function d(n,a,s,c,l,p){return t(),r("div",null,[...a[0]||(a[0]=[o('<h1 id="practicas-de-laboratorio-con-py32f003" tabindex="-1">Prácticas de laboratorio con PY32F003 <a class="header-anchor" href="#practicas-de-laboratorio-con-py32f003" aria-label="Permalink to &quot;Prácticas de laboratorio con PY32F003&quot;">​</a></h1><p>Cada ejercicio se abre como un sketch independiente en <strong>Arduino IDE</strong>. Utiliza la configuración <strong>DevLab PY32F003 Board → PY32F003x4</strong>, reloj <strong>HSI de 24 MHz</strong> y VCC de <strong>3.3 V</strong>.</p><h2 id="descarga" tabindex="-1">Descarga <a class="header-anchor" href="#descarga" aria-label="Permalink to &quot;Descarga&quot;">​</a></h2><p><a href="/unit_devlab_cortex_m_examples/examples/py32f003-ejemplos.zip">Descargar todos los ejemplos de Arduino (ZIP)</a></p><p>Extrae el ZIP y abre el archivo <code>.ino</code> dentro de la carpeta del mismo nombre. No reúnas los cinco archivos en una sola carpeta: cada uno define su propio <code>setup()</code> y <code>loop()</code>.</p><h2 id="ejercicios" tabindex="-1">Ejercicios <a class="header-anchor" href="#ejercicios" aria-label="Permalink to &quot;Ejercicios&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Práctica</th><th>Qué aprenderás</th><th>Material adicional</th><th>Tiempo orientativo</th></tr></thead><tbody><tr><td><a href="./lab01-blink">1. LED Blink</a></td><td>Compilar, cargar por SWD y modificar tiempos</td><td>Ninguno</td><td>20 min</td></tr><tr><td><a href="./lab02-gpio">2. Entrada digital</a></td><td>Leer un pulsador con pull-up</td><td>Pulsador y cables</td><td>15 min</td></tr><tr><td><a href="./lab03-uart">3. UART</a></td><td>Observar mensajes y comprobar eco</td><td>Adaptador USB-UART de 3.3 V</td><td>15 min</td></tr><tr><td><a href="./lab04-adc">4. ADC</a></td><td>Medir una señal analógica y controlar el LED</td><td>Potenciómetro de 10 kΩ; USB-UART para visualizar</td><td>20 min</td></tr><tr><td><a href="./lab05-validacion">5. Falla y validación</a></td><td>Reproducir un fallo, corregirlo y registrar evidencia</td><td>Ninguno</td><td>35 min</td></tr></tbody></table><p>La ruta de dos horas combina las prácticas <strong>1 y 5</strong> con el reconocimiento de hardware y el <a href="./../guide/compilacion">análisis de compilación</a>. Las otras prácticas son ampliaciones según los accesorios disponibles.</p><h2 id="antes-de-empezar" tabindex="-1">Antes de empezar <a class="header-anchor" href="#antes-de-empezar" aria-label="Permalink to &quot;Antes de empezar&quot;">​</a></h2><ul><li><a href="./../py32f003-getting-started/02_0_duino">Configura Arduino IDE y pyOCD</a>.</li><li><a href="./../py32f003-getting-started/03_pinout">Revisa alimentación, pinout y LED Enable</a>.</li><li><a href="./../py32f003-getting-started/04_swd">Comprueba las conexiones SWD</a>.</li></ul><h2 id="registro-de-resultados" tabindex="-1">Registro de resultados <a class="header-anchor" href="#registro-de-resultados" aria-label="Permalink to &quot;Registro de resultados&quot;">​</a></h2><p>Guarda el nombre del ejemplo, versión del paquete, opciones de placa, cambio realizado y comportamiento observado. Compilar correctamente es una parte de la comprobación; cada práctica incluye también pruebas sobre la placa.</p>',12)])])}const h=e(i,[["render",d]]);export{u as __pageData,h as default};
